"<script>(function(){function el(i){return document.getElementById(i)}function esc(s){return String(s==null?'':s).replace(/[&<>\"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]})}function endpoint(p){return '/service/remote/_root/'+p}function req(m,u,body,cb){var x=new XMLHttpRequest();x.open(m,u,true);if(body)x.setRequestHeader('Content-Type','application/x-www-form-urlencoded');x.onreadystatechange=function(){if(x.readyState===4){var d=null;try{d=JSON.parse(x.responseText||'{}')}catch(e){}if(x.status>=200&&x.status<300)cb(null,d||{});else cb((d&&d.error?d.error:'HTTP '+x.status)+(d&&d.rc!==undefined?' rc='+d.rc:''),d)}};x.send(body||null)}var busy=false;function message(t,ok){var m=el('message');m.className=ok?'success':'error';m.textContent=t||''}function phaseText(p){return String(p||'idle').replace(/_/g,' ').toUpperCase()}function render(w){el('worker').textContent='PID '+String(w.pid||'?');el('rpEnabled').textContent=w.remoteplay_enabled?'HABILITADO':'DESATIVADO';el('rpPort').textContent=w.remoteplay_tcp_9295?'RESPONDENDO':'FECHADO';el('serverConfirm').textContent=w.pairing_complete?'REGISTRO CONFIRMADO':(w.pairing_active?'AGUARDANDO':'PARADO');el('clientState').textContent=w.self_pairing_running?'REGISTRANDO...':(w.self_pairing_rc===0?'REGISTRADO':(w.self_pairing_rc!==-999&&w.self_pairing_rc!=null?'RC '+w.self_pairing_rc:'PARADO'));el('clientHttp').textContent=w.self_pairing_http_status?String(w.self_pairing_http_status):'-';el('persisted').textContent=w.registration_persisted?'SALVAS':'NÃO';el('phasePill').textContent=phaseText(w.phase);el('remotePill').textContent='REMOTE ONLINE';el('remotePill').className='pill on';if(w.account_id_saved&&w.account_id&&!el('accountId').value)el('accountId').value=w.account_id;if(w.pairing_pin_ready){var s=String(w.pairing_pin||0);while(s.length<8)s='0'+s;el('pin').textContent=s.substring(0,4)+' '+s.substring(4);el('timer').textContent='PIN interno · '+String(w.pairing_seconds_left||0)+'s restantes'}else{el('pin').textContent='--------';el('timer').textContent=''}el('accountText').textContent=w.account_id_saved?'Account ID salvo: '+w.account_id:'';if(w.registration_persisted&&w.pairing_complete&&w.self_pairing_rc===0){el('badge').textContent='ASTRO PAREADO';el('badge').className='badge ok';el('screenTitle').textContent='Pareamento concluído';el('screenText').textContent='O PS5 registrou o Astro e as credenciais de Remote Play ficaram persistidas.';message('Pareamento concluído. Não precisa repetir esta etapa nas próximas sessões.',true)}else if(w.self_pairing_running){el('badge').textContent='PAREANDO';el('badge').className='badge';el('screenTitle').textContent='Registrando Astro';el('screenText').textContent='O cliente interno está conversando com o Remote Play nativo enquanto o PS5 confirma o registro.'}else if(w.self_pairing_rc!==-999&&w.self_pairing_rc!=null&&w.self_pairing_rc!==0){el('badge').textContent='FALHA NO PAREAMENTO';el('badge').className='badge';message('Falha no cliente de registro: rc='+w.self_pairing_rc+' · HTTP '+(w.self_pairing_http_status||0)+' · reason '+(w.self_pairing_application_reason||0),false)}else{el('badge').textContent=w.registration_persisted?'CREDENCIAIS JÁ SALVAS':'AGUARDANDO';el('badge').className=w.registration_persisted?'badge ok':'badge'}el('diag').textContent='phase='+String(w.phase||'')+'\npair_prepare_rc='+String(w.pairing_prepare_rc)+'  pair_stat='+String(w.pairing_stat)+'  pair_error='+String(w.pairing_error)+'\nclient_rc='+String(w.self_pairing_rc)+'  http='+String(w.self_pairing_http_status)+'  reason='+String(w.self_pairing_application_reason||0);busy=!!w.self_pairing_running;el('pair').disabled=busy}function status(){req('GET',endpoint('status'),null,function(e,w){if(e){message('Astro Remote sem resposta: '+e,false);return}render(w)})}el('pair').onclick=function(){var id=el('accountId').value.trim();if(!id){message('Informe o Account ID que o Astro Lock mostrou.',false);return}if(!/^0x[0-9a-fA-F]{1,16}$/.test(id)&&!/^[0-9]+$/.test(id)){message('Account ID inválido. Use hexadecimal começando com 0x ou decimal.',false);return}if(!confirm('Parear o próprio Astro Remote com este PS5 usando '+id+'?'))return;message('Iniciando autopareamento...',true);req('POST',endpoint('pairing/self'),'account_id='+encodeURIComponent(id),function(e,w){if(e){message('Não foi possível iniciar: '+e,false);return}render(w)})};el('cancel').onclick=function(){req('POST',endpoint('pairing/cancel'),'',function(e,w){if(e){message(e,false);return}message('Pareamento cancelado.',true);render(w)})};status();setInterval(status,1000)})();</script></body></html>";

